import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { logger } from "../lib/logger.js";
import type { ImageAsset, ResolvedImage } from "./types.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const CONTENT_DIR = path.resolve(__dirname, "../../content/blog");

/**
 * `media.json` is generated by `npm run build:blog-images` from the source
 * photographs. It carries intrinsic dimensions and the generated variant URLs,
 * which is what lets the SSR markup emit real width/height (no CLS) and honest
 * srcsets instead of guessed numbers.
 */
type ManifestEntry = {
  width: number;
  height: number;
  webp?: { src: string; width: number; height: number }[];
  jpg?: { src: string; width: number; height: number }[];
  og?: string | null;
};

type Manifest = {
  version: number;
  images: Record<string, ManifestEntry>;
};

let manifestCache: Manifest | null = null;
let manifestMtime = -1;
const missingReported = new Set<string>();

function readManifest(): Manifest {
  const file = path.join(CONTENT_DIR, "media.json");
  let mtime = -1;
  try {
    mtime = fs.statSync(file).mtimeMs;
  } catch {
    if (manifestCache) logger.warn("[blog] media.json disappeared — using cached manifest");
    manifestCache ??= { version: 1, images: {} };
    manifestMtime = mtime;
    return manifestCache;
  }
  if (manifestCache && manifestMtime === mtime) return manifestCache;
  try {
    const parsed = JSON.parse(fs.readFileSync(file, "utf8")) as Manifest;
    manifestCache = {
      version: typeof parsed.version === "number" ? parsed.version : 1,
      images: parsed.images ?? {},
    };
  } catch (err) {
    logger.warn({ err }, "[blog] media.json is not valid JSON — image metadata unavailable");
    manifestCache ??= { version: 1, images: {} };
  }
  manifestMtime = mtime;
  return manifestCache;
}

/** Test hook: forget the cached manifest. */
export function resetMediaCache(): void {
  manifestCache = null;
  manifestMtime = -1;
  missingReported.clear();
}

function srcsetFor(variants: { src: string; width: number }[] | undefined): string {
  if (!variants?.length) return "";
  return [...variants]
    .sort((a, b) => a.width - b.width)
    .map((variant) => `${variant.src} ${variant.width}w`)
    .join(", ");
}

const FALLBACK_WIDTH = 1200;
const FALLBACK_HEIGHT = 750;

/** Resolve a frontmatter image against the manifest. Never throws. */
export function resolveImage(
  asset: ImageAsset | null | undefined,
  fallbackAlt = "",
): ResolvedImage | null {
  if (!asset?.src) return null;
  const entry = readManifest().images[asset.src];
  if (!entry && !missingReported.has(asset.src)) {
    missingReported.add(asset.src);
    logger.warn(
      { src: asset.src },
      "[blog] image missing from media.json — run `npm run build:blog-images`",
    );
  }
  const largestJpg = [...(entry?.jpg ?? [])].sort((a, b) => b.width - a.width)[0];
  return {
    src: largestJpg?.src ?? asset.src,
    webpSrcset: srcsetFor(entry?.webp),
    jpgSrcset: srcsetFor(entry?.jpg),
    width: largestJpg?.width ?? entry?.width ?? FALLBACK_WIDTH,
    height: largestJpg?.height ?? entry?.height ?? FALLBACK_HEIGHT,
    og: entry?.og ?? null,
    alt: asset.alt.trim() || fallbackAlt,
    credit: asset.credit,
    creditUrl: asset.creditUrl,
    focalPoint: asset.focalPoint ?? null,
  };
}

/** Every image referenced by the blog, keyed by source path — used by tests. */
export function manifestImageKeys(): string[] {
  return Object.keys(readManifest().images);
}
